(()=>{'use strict';const $=id=>document.getElementById(id);$('check-evidence').onclick=async()=>{const button=$('check-evidence'),status=$('check-evidence-status'),box=$('check-evidence-results');button.disabled=true;status.textContent='Checking your saved cloud evidence…';try{if(!window.designerCloudReady?.())throw Error('Wait for Cloud saved before checking sources.');const response=await fetch('/api/designer/investigate',{method:'POST'}),data=await response.json();if(!response.ok)throw Error(data.error);document.dispatchEvent(new CustomEvent('fashion-evidence-checked',{detail:data.results}));box.replaceChildren();if(!data.results.length)status.textContent='Save a real public source URL first.';else status.textContent=data.notice;for(const r of data.results){const card=document.createElement('article');card.className='record';const heading=document.createElement('h3');heading.textContent=r.state;card.append(heading);for(const text of [r.title,'Checked: '+r.checkedAt,r.reason,r.identity,r.brandMention?'Recorded brand name appears in the returned page. Identity still requires confirmation.':null]){if(!text)continue;const p=document.createElement('p');p.textContent=text;card.append(p);}try{const u=new URL(r.url);if(['http:','https:'].includes(u.protocol)&&!u.username&&!u.password){const link=document.createElement('a');link.textContent='Open source evidence';link.href=u.href;link.target='_blank';link.rel='noopener noreferrer';card.append(link);}}catch{}const connect=document.createElement('a');connect.textContent='Review platform connection';connect.href='#connections';connect.style.display='block';connect.onclick=()=>{$('connection-source').textContent='Checked source: '+r.url+' · '+r.state;};card.append(connect);box.append(card);}}catch(e){status.textContent=e.message||'Source check unavailable';}finally{button.disabled=false;}};})();
